/**
 * Garment templates for the Build-Your-Own Mockup builder (`/design`).
 * See docs/04-MOCKUP-BUILDER-SPEC.md.
 *
 * The images in `public/garments/{garment}/{view}/` are original vector drawings
 * generated by `node scripts/garments/build.mjs` (edit `scripts/garments/shapes.mjs`,
 * then rebuild). They are deliberately neutral: no site theme on the garments, so
 * the customer's colors and artwork are the only thing on show.
 *
 * Per view, layers composite bottom to top:
 *   1. each zone mask filled with its color (`source-in`)
 *   2. `shading.png` with `multiply` (folds, seams, texture)
 *   3. `highlight.png` with `screen` at `highlightOpacity(hex)` (sheen; stronger on dark fabric)
 *   4. clip everything to the shading layer's alpha (the garment silhouette)
 *   5. the customer's artwork, clipped to the active print area, then shading again on top
 * `base.png` is a ready-made white composite for thumbnails and loading states.
 *
 * Print-area rects are in template pixels (each view's `width` x `height`).
 */

export type GarmentId = "tshirt" | "raglan" | "hoodie" | "hat" | "polo" | "tank";
export type ViewId = "front" | "back";

export type GarmentColor = { name: string; hex: string };

export type ColorZone = { id: string; label: string };

export type PrintArea = {
  id: string;
  label: string;
  rect: { x: number; y: number; w: number; h: number };
  maxInches: { w: number; h: number };
};

export type GarmentView = {
  id: ViewId;
  label: string;
  width: number;
  height: number;
  /** Zones that appear in this view (a subset of the garment's zones). */
  zones: string[];
  layers: {
    base: string;
    shading: string;
    highlight: string;
    mask: Record<string, string>;
  };
  printAreas: PrintArea[];
};

export type GarmentConfig = {
  id: GarmentId;
  name: string;
  description: string;
  colorZones: ColorZone[];
  /** Default color per zone (hex). */
  defaultColors: Record<string, string>;
  palette: GarmentColor[];
  /** Customers may pick any hex; the UI notes "we'll match the closest available blank". */
  allowCustomHex: boolean;
  views: GarmentView[];
  sizes: string[];
};

