export const GARMENT_IDS = GARMENTS.map((g) => g.id) as GarmentId[];

export function getGarment(id: GarmentId): GarmentConfig {
  const g = GARMENTS.find((x) => x.id === id);
  if (!g) throw new Error(`Unknown garment: ${id}`);
  return g;
}

const HEX = /^#[0-9a-f]{6}$/i;

export function isHexColor(value: string): boolean {
  return HEX.test(value);
}

/** Perceived brightness (0 = black, 1 = white) of a #rrggbb color (Rec. 709 weights on sRGB values). */
export function luma(hex: string): number {
  if (!isHexColor(hex)) throw new Error(`Bad hex color: ${hex}`);
  const [r, g, b] = [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16) / 255);
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}

/**
 * Opacity for the `screen` highlight layer. Light fabric barely needs it (multiply
 * shading does the work); dark fabric needs sheen or it reads as a flat silhouette.
 * Must match `highlightOpacity` in scripts/garments/build.mjs.
 */
export function highlightOpacity(hex: string): number {
  return +(0.15 + 0.85 * (1 - luma(hex))).toFixed(3);
}

/** Printed size in inches for an artwork box drawn in template px on a print area. */
export function printedInches(area: PrintArea, box: { w: number; h: number }) {
  const pxPerInch = area.rect.w / area.maxInches.w;
  return { w: box.w / pxPerInch, h: box.h / pxPerInch };
}
